First, let's see the project structure:
```directory
/Users/m/web_app
├── src
│   ├── components
│   │   ├── Header.tsx
│   │   ├── Footer.tsx
│   │   ├── ProductCard.tsx
│   │   ├── ProductList.tsx
│   │   ├── ProductDetail.tsx
│- index.tsx
├── public
│   ├── logo.png
│   ├── favicon.ico
│- next.config.js
├── package.json
├── tailwind.config.js
└── tsconfig.json
```

The app uses React with Vite. The product listing page is in `src/components/ProductList.tsx` and the product detail page is in `src/components/ProductDetail.tsx`.

The product listing page:
```tsx
import React from 'react';
import { Product } } from '../types';
import ProductCard from './ProductCard';

interface ProductListProps {
  products: Product[];
}

export default function ProductList({ products }: ProductListProps) {
  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
      {products.map((product) => (
        <ProductCard key={product.id} product={product} />
      ))}
    </div>
  );
}
```

